import unittest

class WindowTests(unittest.TestCase):
    def test_left_boundary_excluded(self):
        self.assertEqual(count_recent([40, 41, 99, 100], 100, 60), 3)

    def test_right_boundary_included(self):
        self.assertEqual(count_recent([100], 100, 60), 1)

    def test_future_events_excluded(self):
        self.assertEqual(count_recent([101, 102], 100, 60), 0)

    def test_expired_events_excluded(self):
        self.assertEqual(count_recent([1, 20, 39], 100, 60), 0)

    def test_empty_window(self):
        self.assertEqual(count_recent([], 100, 60), 0)

    def test_repeated_boundary_events(self):
        self.assertEqual(count_recent([40, 40, 41], 100, 60), 1)

